mapper.select:
select
con.Con_Name as conName, con.Con_Party_B_Id as conPartyBId, met.Met_Name as metName, c1.C_Name_History as wiUnitNameHistory, c2.C_Name_History as conPartyBNameHistory, c1.C_Name as wiUnitName, c2.C_Name as conPartyBName, c1.C_Abbreviation as wiUnitAbbName, c2.C_Abbreviation as conPartyBAbbName, mn.* from Me_Inspection_Report mn left join Con_Contract con on con.Con_Id=mn.Con_Id
left join Me_Witness_Inspection wi on wi.Wi_Id=mn.Wi_Id left join Me_Enter_Apply_Dtl ead on ead.Ead_Id=wi.Ead_Id left join Me_Type_Library met on met.Met_Id=ead.Met_Id left join SYS_Company c1 on wi.Wi_Unit_Id=c1.C_Id left join SYS_Company c2 on con.Con_Party_B_Id=c2.C_Id ${params.authSql}
and mn.Te_Id = #{params.teId}
and con.Con_Party_B_Id = #{params.conPartyBId}
and mn.P_Id = #{params.pId}
and mn.Con_Id = #{params.conId}
and wi.Wi_Unit_Id = #{params.wiUnitId}
and met.Met_Name like concat('%',#{params.metName},'%')
and likePname(#{params.pName},pro.P_Id)=true
and pro.P_Name like concat('%',#{params.pName},'%')
and con.Con_Name like concat('%',#{params.conName},'%')
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Ir_Create_Time desc
